-- Run against a new/empty Supabase database.
CREATE TABLE "Users" ("Roll_No" VARCHAR(20) PRIMARY KEY, "Name" VARCHAR(50) NOT NULL, "Email" VARCHAR(100) UNIQUE NOT NULL, "Phone_No" VARCHAR(15) UNIQUE NOT NULL);
CREATE TABLE "Organizers" ("Organizer_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Roll_No" VARCHAR(20) UNIQUE NOT NULL, "Organization_Name" VARCHAR(100) NOT NULL, "Designation" VARCHAR(50), FOREIGN KEY ("Roll_No") REFERENCES "Users"("Roll_No") ON UPDATE CASCADE ON DELETE CASCADE);
CREATE TABLE "Venues" ("Venue_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Venue_Name" VARCHAR(100) NOT NULL, "Building" VARCHAR(100), "Floor" VARCHAR(20), "Room_Number" VARCHAR(50), "Capacity" INTEGER NOT NULL CHECK ("Capacity" > 0));
CREATE TABLE "Events" ("Event_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Event_Name" VARCHAR(100) NOT NULL, "Description" TEXT, "Category" VARCHAR(50) NOT NULL, "Event_Date" DATE NOT NULL, "Start_Time" TIME NOT NULL, "End_Time" TIME NOT NULL, "Venue_ID" INTEGER NOT NULL, "Event_Capacity" INTEGER NOT NULL CHECK ("Event_Capacity" > 0), "Registration_Deadline" DATE, FOREIGN KEY ("Venue_ID") REFERENCES "Venues"("Venue_ID") ON UPDATE CASCADE ON DELETE RESTRICT, CHECK ("End_Time" > "Start_Time"));
CREATE TABLE "Event_Organizers" ("Organizer_ID" INTEGER NOT NULL, "Event_ID" INTEGER NOT NULL, PRIMARY KEY ("Organizer_ID", "Event_ID"), FOREIGN KEY ("Organizer_ID") REFERENCES "Organizers"("Organizer_ID") ON UPDATE CASCADE ON DELETE CASCADE, FOREIGN KEY ("Event_ID") REFERENCES "Events"("Event_ID") ON UPDATE CASCADE ON DELETE CASCADE);
CREATE TABLE "Registrations" ("Registration_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Roll_No" VARCHAR(20) NOT NULL, "Event_ID" INTEGER NOT NULL, "Registration_Date" DATE DEFAULT CURRENT_DATE, FOREIGN KEY ("Roll_No") REFERENCES "Users"("Roll_No") ON UPDATE CASCADE ON DELETE CASCADE, FOREIGN KEY ("Event_ID") REFERENCES "Events"("Event_ID") ON UPDATE CASCADE ON DELETE CASCADE, UNIQUE ("Roll_No", "Event_ID"));
CREATE TABLE "Payments" ("Payment_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Roll_No" VARCHAR(20) NOT NULL, "Payment_Date" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP, "Amount" NUMERIC(10,2) NOT NULL CHECK ("Amount" >= 0), "Transaction_ID" VARCHAR(100) UNIQUE NOT NULL, FOREIGN KEY ("Roll_No") REFERENCES "Users"("Roll_No") ON UPDATE CASCADE ON DELETE CASCADE);
CREATE TABLE "Suppliers" ("Supplier_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Supplier_Name" VARCHAR(100) NOT NULL, "Category" VARCHAR(50) NOT NULL, "Phone_No" VARCHAR(15) NOT NULL, "Email" VARCHAR(100) UNIQUE);
CREATE TABLE "Event_Suppliers" ("Event_ID" INTEGER NOT NULL, "Supplier_ID" INTEGER NOT NULL, PRIMARY KEY ("Event_ID", "Supplier_ID"), FOREIGN KEY ("Event_ID") REFERENCES "Events"("Event_ID") ON UPDATE CASCADE ON DELETE CASCADE, FOREIGN KEY ("Supplier_ID") REFERENCES "Suppliers"("Supplier_ID") ON UPDATE CASCADE ON DELETE CASCADE);

